import { createRouter, createWebHistory } from 'vue-router'
import PkIndexView from "@/views/calendar/CalendarIndexView.vue";
import RanklistIndexView from "@/views/memorandum/MemorandumIndexView.vue";
import RecordIndexView from "@/views/event/EventIndexView.vue";
import UserBotIndexView from "@/views/user/information/UserInformationIndexView.vue";
import NotFound from "@/views/error/NotFound.vue";

const routes = [
  {
    path: "/",
    name: "home",
    redirect: "/calendar/",
  },
  {
    path: "/calendar/",
    name: "calendar_index",
    component: CalendarIndexView.vue,
  },
  {
    path: "/memorandum/",
    name: "memorandum_index",
    component: MemorandumIndexView,
  },
  {
    path: "/event/",
    name: "event_index",
    component: EventIndexView,
  },
  {
    path: "/user/information/",
    name: "user_information_index",
    component: UserInformationIndexView,
  },
  {
    path: "/404/",
    name: "404",
    component: NotFound,
  },
  {
    path: "/:catchAll(.*)",
    redirect: "/404/",
  }
]


const router = createRouter({
  history: createWebHistory(),
  routes
})

export default router
